export default function prepareMessages({ events }) {
  if (!Array.isArray(events) || events.length > 25) throw new Error('Expected at most 25 incoming Gmail events.');
  const messageIds = [], seen = new Set();
  for (const event of events) {
    const id = event?.messageId;
    if (typeof id !== 'string' || !id.trim() || seen.has(id)) throw new Error('Incoming Gmail message IDs must be nonempty and unique.');
    seen.add(id); messageIds.push(id);
  }
  return { messageIds, count: messageIds.length };
}

