export function normalizeBodies(messageIds, responses) {
  if (!Array.isArray(messageIds) || !Array.isArray(responses) || messageIds.length !== responses.length) throw new Error('Gmail body count differs from the incoming message count.');
  const messages = messageIds.map((messageId, index) => {
    const response = responses[index];
    if (response?.messageId !== messageId || typeof response.body !== 'string') throw new Error('Gmail returned a different message ID or invalid body.');
    return { messageId, body: response.body };
  });
  return { messages };
}
export default async function readMessageBodies({ messageIds }, context) {
  const responses = [];
  for (const messageId of messageIds) {
    context.signal?.throwIfAborted();
    responses.push(await context.actions.call('gmail.get_message', { messageId }));
  }
  return normalizeBodies(messageIds, responses);
}

