export default async function addLabelsToMessages({ plans }, context) {
  let updatedCount = 0;
  for (const plan of plans) {
    context.signal?.throwIfAborted();
    if (!plan.labelIds.length) continue;
    const response = await context.actions.call('gmail.add_label_to_email', { messageId: plan.messageId, addLabelIds: plan.labelIds });
    if (response?.messageId !== plan.messageId) throw new Error('Gmail returned a label confirmation for a different message.');
    updatedCount++;
  }
  return { decisions: plans, updatedCount };
}

