export default async function classifyMessages({ messages }, context) {
  const classifications = [];
  for (const message of messages) {
    context.signal?.throwIfAborted();
    const result = await context.workflows.call('classify-message', message);
    if (result?.messageId !== message.messageId) throw new Error('The classification belongs to a different Gmail message.');
    classifications.push(result);
  }
  return { classifications };
}

