export default function validateLabels({ messageId, completion }) {
  const allowed = ['Inquiry', 'Partnership', 'Notification'];
  if (typeof messageId !== 'string' || !messageId.trim() || !completion || typeof completion !== 'object' || Array.isArray(completion) || !Array.isArray(completion.labels)) throw new Error('Classification must be an object containing a labels array.');
  const labels = [];
  for (const label of completion.labels) {
    if (typeof label !== 'string' || !allowed.includes(label)) throw new Error('Classification contains an unknown Gmail label.');
    if (!labels.includes(label)) labels.push(label);
  }
  return { messageId, labels };
}
